mapper.select:
   SELECT a.*,(SELECT r.type FROM customer_request r WHERE r.appointment_id=a.id AND r.type IN ('CANCEL','RESCHEDULE') AND r.status IN ('PENDING','PROCESSING') ORDER BY r.id LIMIT 1) AS pending_request_type FROM appointment a WHERE 1=1 
   AND customer_id=#{customer}

   AND photographer_id=#{photographer}

   AND start_time >= #{date} AND start_time < DATE_ADD(#{date},INTERVAL 1 DAY)
ORDER BY start_time DESC,id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM appointment WHERE 1=1 
AND customer_id=#{customer}

AND photographer_id=#{photographer}

AND start_time >= #{date} AND start_time < DATE_ADD(#{date},INTERVAL 1 DAY)
